typedef unsigned int u_int;
typedef unsigned long long u_long;

struct nglTexture { unsigned short Width, Height; };
struct nglQuadVertex { float X, Y, U, V; u_int Color; };
struct nglQuad { nglQuadVertex Verts[4]; float Z; };

struct nglVector
{
  float v[4];
  nglVector(float x, float y, float z, float w) { v[0]=x; v[1]=y; v[2]=z; v[3]=w; }
  float& operator[](int i) { return v[i]; }
};
struct nglScene
{
  nglTexture* RenderTarget;
  float NearZ, FarZ;
  float ViewToScreen[4][4];
};

extern nglScene* nglCurScene;
extern u_int nglGifRegCount;
extern unsigned char nglGifRegIdx[128];
extern u_long nglGifRegVal[128];
void sceVu0ApplyMatrix(float*, float (*)[4], float*);

inline int nglFTOI(float input)
{
  register float output;
  __asm__ volatile ("cvt.w.s %0, %1" : "=f" (output) : "f" (input));
  return (int&)output;
}
inline u_int nglViewZToGS(float Z)
{
  float _Z = Z;
  if (_Z < nglCurScene->NearZ) _Z = nglCurScene->NearZ;
  if (_Z > nglCurScene->FarZ) _Z = nglCurScene->FarZ;
  nglVector V(0.0f, 0.0f, _Z, 1.0f);
  sceVu0ApplyMatrix(V.v, nglCurScene->ViewToScreen, V.v);
  V[2] /= V[3];
  return nglFTOI(V[2] * 16.0f);
}
inline u_int nglScreenXToGS(float X) { return (int)((X + 2048 - (nglCurScene->RenderTarget->Width / 2)) * 16); }
inline u_int nglScreenYToGS(float Y) { float YOfs = 0.0f; return (int)((Y + 2048 + YOfs - (nglCurScene->RenderTarget->Height / 2)) * 16); }
inline void nglVif1AddRawGSReg(u_int Reg, u_long Val)
{
  nglGifRegIdx[nglGifRegCount] = Reg;
  nglGifRegVal[nglGifRegCount] = Val;
  nglGifRegCount++;
}

#define SCE_GS_PRIM 0
#define SCE_GS_RGBAQ 1
#define SCE_GS_ST 2
#define SCE_GS_XYZ2 5
#define SCE_GS_PRIM_TRISTRIP 4
#define SCE_GS_SET_PRIM(prim,iip,tme,fge,abe,aa1,fst,ctxt,fix) ((u_long)(prim)|((u_long)(iip)<<3)|((u_long)(tme)<<4)|((u_long)(fge)<<5)|((u_long)(abe)<<6)|((u_long)(aa1)<<7)|((u_long)(fst)<<8)|((u_long)(ctxt)<<9)|((u_long)(fix)<<10))
#define SCE_GS_SET_RGBAQ(r,g,b,a,q) ((u_long)(r)|((u_long)(g)<<8)|((u_long)(b)<<16)|((u_long)(a)<<24)|((u_long)(q)<<32))
#define SCE_GS_SET_ST(s,t) ((u_long)(s)|((u_long)(t)<<32))
#define SCE_GS_SET_XYZ(x,y,z) ((u_long)(x)|((u_long)(y)<<16)|((u_long)(z)<<32))

void nglVif1AddQuadVerts( nglQuad* Quad )
{
  u_int z = nglViewZToGS( Quad->Z );

  nglVif1AddRawGSReg( SCE_GS_PRIM, SCE_GS_SET_PRIM( SCE_GS_PRIM_TRISTRIP, 0, 0, 0, 0, 0, 0, 0, 0 ) );
  for ( int j = 0; j < 4; j++ )
  {
    nglQuadVertex* Vert = &Quad->Verts[j];
    nglVif1AddRawGSReg( SCE_GS_RGBAQ, SCE_GS_SET_RGBAQ( Vert->Color, 0, 0, 0, 0x3f800000 ) );  // Q == 1.0f.
    nglVif1AddRawGSReg( SCE_GS_ST, SCE_GS_SET_ST( *(u_int*)&Vert->U, *(u_int*)&Vert->V ) );
    u_int x = nglScreenXToGS( Vert->X );
    u_int y = nglScreenYToGS( Vert->Y );
    nglVif1AddRawGSReg( SCE_GS_XYZ2, SCE_GS_SET_XYZ( x, y, z ) );
  }
}
